  package    se . fishtank . css . selectors ;   import   java . util . List ;  import     se . fishtank . css . util . Assert ;   public class Selector  {   public static final String  UNIVERSAL_TAG = "*" ;   public static enum Combinator  {  INITIAL ,  DESCENDANT ,  CHILD ,  ADJACENT_SIBLING ,  GENERAL_SIBLING }   private final String  tagName ;   private final Combinator  combinator ;   private final  List  < Specifier >  specifiers ;   public Selector  ( )  {    this . tagName = UNIVERSAL_TAG ;    this . combinator =  Combinator . INITIAL ;    this . specifiers = null ; }   public Selector  (  String tagName ,  Combinator combinator )  {   Assert . notNull  ( tagName , "tagName is null!" ) ;   Assert . notNull  ( combinator , "combinator is null!" ) ;    this . tagName = tagName ;    this . combinator = combinator ;    this . specifiers = null ; }   public Selector  (  String tagName ,   List  < Specifier > specifiers )  {   Assert . notNull  ( tagName , "tagName is null!" ) ;    this . tagName = tagName ;    this . combinator =  Combinator . INITIAL ;    this . specifiers = specifiers ; }   public Selector  (  String tagName ,  Combinator combinator ,   List  < Specifier > specifiers )  {   Assert . notNull  ( tagName , "tagName is null!" ) ;   Assert . notNull  ( combinator , "combinator is null!" ) ;    this . tagName = tagName ;    this . combinator = combinator ;    this . specifiers = specifiers ; }   public String getTagName  ( )  {  return tagName ; }   public Combinator getCombinator  ( )  {  return combinator ; }   public  List  < Specifier > getSpecifiers  ( )  {  return specifiers ; }   public boolean hasSpecifiers  ( )  {  return   specifiers != null &&  !  specifiers . isEmpty  ( ) ; } }